package dev.navifold.player;
import org.junit.Test;import org.json.*;import java.util.*;import static org.junit.Assert.*;
public class FlowPolicyTest {
 JSONObject song(String id,String genre)throws Exception{return new JSONObject().put("id",id).put("artist","Artist").put("albumId",id+"-album").put("genre",genre);}
 @Test public void naturalBlocksRegionalDriftEvenWithSharedPopTag()throws Exception{JSONObject seed=song("a","Pop"),j=song("j","Pop").put("genres",new JSONArray().put("Pop").put(new JSONObject().put("name","J-Pop")));assertFalse(FlowPolicy.allows(seed,j,1));assertFalse(FlowPolicy.allows(seed,song("k","K-pop"),1));assertTrue(FlowPolicy.allows(seed,song("s","Synth-pop"),1));assertFalse(FlowPolicy.allows(seed,song("jazz","Jazz"),1));}
 @Test public void strictAndDiverseHaveDifferentConstraints()throws Exception{JSONObject pop=song("a","Pop"),synth=song("s","Synth-pop"),j=song("j","J-pop");assertFalse(FlowPolicy.allows(pop,synth,0));assertTrue(FlowPolicy.allows(pop,j,2));assertTrue(FlowPolicy.allows(j,song("j2","J-pop"),0));}
 @Test public void explicitLanguageMismatchIsBlockedButNamesAreNotGuessed()throws Exception{JSONObject en=song("a","Pop").put("language","en"),ja=song("b","Pop").put("language","jpn");assertFalse(FlowPolicy.allows(en,ja,1));assertTrue(FlowPolicy.allows(en,song("b","Pop").put("language","eng"),1));assertTrue(FlowPolicy.allows(en,song("b","Pop").put("artist","日本語の名前"),1));}
 @Test public void missingGenreDoesNotSilentlyBroaden()throws Exception{assertFalse(FlowPolicy.allows(song("a","Pop"),song("b",""),1));assertFalse(FlowPolicy.allows(song("a",""),song("b","Jazz"),0));assertFalse(FlowPolicy.allows(song("a",""),song("b","Jazz").put("artist","Another"),1));}
 @Test public void anchorStaysOnSuggestionsAndAlbumContinuation()throws Exception{JSONObject a=song("a","Pop"),b=song("b","J-pop");assertFalse(FlowPolicy.shouldAnchor(a,b,true,false));assertFalse(FlowPolicy.shouldAnchor(a,b,true,true));assertTrue(FlowPolicy.shouldAnchor(a,b,false,false));assertFalse(FlowPolicy.shouldAnchor(a,song("a2","Pop").put("albumId","a-album"),false,false));}
 @Test public void guardCannotBeBypassedByRemoteOrFallbackOrder()throws Exception{JSONObject a=song("a","Pop"),pop=song("b","Pop"),j=song("c","J-pop");assertEquals(Collections.singletonList(pop),FlowPolicy.filter(Arrays.asList(j,pop),a,1));assertTrue(FlowPolicy.filter(Collections.singletonList(j),a,1).isEmpty());}
 @Test public void scalarRegionalTagCannotHideBehindBroadGenreArray()throws Exception{JSONObject pop=song("a","Pop"),j=song("b","J-pop").put("genres",new JSONArray().put("Pop"));assertFalse(FlowPolicy.allows(pop,j,1));}
 @Test public void missingPlaybackTagsDoNotEraseIndexedAnchor()throws Exception{JSONObject merged=FlowPolicy.anchorTags(song("a","Pop"),song("a","").put("genres",new JSONArray()));assertEquals("Pop",merged.getString("genre"));}
 @Test public void normalizeWhitespaceWithoutLosingLetters(){assertEquals("synthpop",FlowPolicy.norm("Ｓｙｎｔｈ　Ｐｏｐ"));assertEquals("artist",FlowPolicy.norm("Artist"));}
 @Test public void scopedMetadataPreservesLanguageAndScene()throws Exception{JSONObject x=SongMetadata.safe(song("a","Pop").put("language","en").put("languages",new JSONArray().put("eng")).put("musicScene","jp").put("password","secret"));assertEquals("en",x.getString("language"));assertEquals("jp",x.getString("musicScene"));assertFalse(x.has("password"));}
}
